import React from "react";

// Home-page links to the static blog articles (generated by scripts/build-blog.js).
// Plain <a> on purpose: /blog/* are static HTML files, not React routes.
export const BlogTeaser = ({ posts, labels }) => {
  const L = labels || {};
  const featured = (posts || []).filter((p) => p.featured);
  if (!featured.length) return null;
  return (
    <div id="blog-teaser" className="text-center">
      <div className="container">
        <div className="section-title">
          <h2>{L.title}</h2>
          <p>{L.subtitle}</p>
        </div>
        <div className="row blog-teaser-row">
          {featured.map((p) => (
            <div key={p.slug} className="col-sm-6 col-md-3">
              <a className="blog-teaser-card" href={`/blog/${p.slug}/`}>
                <i className={p.icon}></i>
                <span className="blog-teaser-category">{p.category}</span>
                <h3>{p.title}</h3>
              </a>
            </div>
          ))}
        </div>
        <a href="/blog/" className="btn btn-custom btn-lg">
          {L.all}
        </a>
      </div>
    </div>
  );
};
